mapper.select:
select part_code, parent_part_code, sum(apply_num) apply_num
from ${dynamicTableNameProxy.collaborateProduceExtend}
where contract_code = #{contractCode}
  and delete_flag = false
  and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
group by part_code, parent_part_code

mapper.update:
update ${dynamicTableNameProxy.collaborateProduceExtend}
set pick_Status =1
where contract_code = #{contractCode}
  and delete_flag = false
  and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
